package modelcatalog

import (
	"fmt"
	"sort"
	"strconv"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/sampling"
)

// Surface identifies the consumer-specific naming surface for a model target.
type Surface string

const (
	SurfaceAgentOpenAI    Surface = "agent.openai"
	SurfaceAgentAnthropic Surface = "agent.anthropic"
	SurfaceCodex          Surface = "codex"
	SurfaceClaudeCode     Surface = "claude-code"
	SurfaceGemini         Surface = "gemini"
)

// ResolveOptions configures how model references are resolved.
type ResolveOptions struct {
	Surface         Surface
	AllowDeprecated bool
}

// Catalog resolves logical model references into concrete consumer-specific model IDs.
type Catalog struct {
	manifest       manifest
	manifestSrc    string
	aliasToID      map[string]string
	profileEntries map[string]profileEntry
}

// SurfacePolicy captures optional routing metadata for a resolved surface.
type SurfacePolicy struct {
	ReasoningDefault       reasoning.Reasoning
	PlacementOrder         []string
	MaxInputCostPerMTokUSD *float64
	FailurePolicy          string
}

// Metadata describes the loaded manifest.
type Metadata struct {
	ManifestSource  string
	ManifestVersion int
	CatalogVersion  string
}

// Profile describes one named catalog profile.
type Profile struct {
	Name                string
	Target              string
	CompatibilityTarget string
	MinPower            int
	MaxPower            int
	ProviderPreference  string
}

// Alias describes one catalog alias.
type Alias struct {
	Name        string
	Target      string
	Deprecated  bool
	Replacement string
}

// ResolvedTarget is the resolved output for a model reference.
type ResolvedTarget struct {
	Ref             string
	Profile         string
	Family          string
	CanonicalID     string
	ConcreteModel   string
	SurfacePolicy   SurfacePolicy
	Deprecated      bool
	Replacement     string
	CatalogVersion  string
	ManifestSource  string
	ManifestVersion int
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64
	CostOutputPerM     float64
	CostCacheReadPerM  float64
	CostCacheWritePerM float64
	// Context
	ContextWindow int
	// Benchmarks
	SWEBenchVerified float64
	LiveCodeBench    float64
	BenchmarkAsOf    string
	// OpenRouter
	OpenRouterRefID string
}

// TierModel is one concrete model entry referenced by a catalog tier.
type TierModel struct {
	ID    string
	Entry ModelEntry
}

// ModelEligibility describes whether a catalog model can participate in
// unpinned automatic routing or only explicit model pins.
type ModelEligibility struct {
	Power        int
	ExactPinOnly bool
	AutoRoutable bool
}

// Metadata returns the loaded manifest metadata for inspection surfaces.
func (c *Catalog) Metadata() Metadata {
	return Metadata{
		ManifestSource:  c.manifestSrc,
		ManifestVersion: c.manifest.Version,
		CatalogVersion:  c.manifest.CatalogVersion,
	}
}

// Profiles returns all named profiles in deterministic order.
func (c *Catalog) Profiles() []Profile {
	names := make([]string, 0, len(c.profileEntries))
	for name := range c.profileEntries {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]Profile, 0, len(names))
	for _, name := range names {
		entry := c.profileEntries[name]
		compatTarget := profileCompatibilityTarget(entry)
		out = append(out, Profile{
			Name:                name,
			Target:              compatTarget,
			CompatibilityTarget: compatTarget,
			MinPower:            entry.MinPower,
			MaxPower:            entry.MaxPower,
			ProviderPreference:  normalizedProviderPreference(entry.ProviderPreference),
		})
	}
	return out
}

// Profile returns one named profile definition.
func (c *Catalog) Profile(name string) (Profile, bool) {
	entry, ok := c.profileEntries[strings.TrimSpace(name)]
	if !ok {
		return Profile{}, false
	}
	compatTarget := profileCompatibilityTarget(entry)
	return Profile{
		Name:                strings.TrimSpace(name),
		Target:              compatTarget,
		CompatibilityTarget: compatTarget,
		MinPower:            entry.MinPower,
		MaxPower:            entry.MaxPower,
		ProviderPreference:  normalizedProviderPreference(entry.ProviderPreference),
	}, true
}

// Aliases returns all target aliases in deterministic order.
func (c *Catalog) Aliases() []Alias {
	names := make([]string, 0, len(c.aliasToID))
	for name := range c.aliasToID {
		names = append(names, name)
	}
	sort.Strings(names)
	out := make([]Alias, 0, len(names))
	for _, name := range names {
		targetID := c.aliasToID[name]
		target := c.manifest.Targets[targetID]
		status := normalizedStatus(target.Status)
		out = append(out, Alias{
			Name:        name,
			Target:      targetID,
			Deprecated:  status != statusActive,
			Replacement: target.Replacement,
		})
	}
	return out
}

// UnknownReferenceError indicates that a reference is not known to the catalog.
type UnknownReferenceError struct {
	Ref string
}

func (e *UnknownReferenceError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown reference %q", e.Ref)
}

// MissingSurfaceError indicates that a target cannot be projected to the requested surface.
type MissingSurfaceError struct {
	CanonicalID string
	Surface     Surface
}

func (e *MissingSurfaceError) Error() string {
	return fmt.Sprintf("modelcatalog: target %q has no mapping for surface %q", e.CanonicalID, e.Surface)
}

// DeprecatedTargetError indicates that a deprecated or stale target was resolved in strict mode.
type DeprecatedTargetError struct {
	CanonicalID string
	Status      string
	Replacement string
}

func (e *DeprecatedTargetError) Error() string {
	if e.Replacement == "" {
		return fmt.Sprintf("modelcatalog: target %q is %s", e.CanonicalID, e.Status)
	}
	return fmt.Sprintf("modelcatalog: target %q is %s; use %q", e.CanonicalID, e.Status, e.Replacement)
}

// UnknownTargetError indicates an internal invariant break where a referenced target is absent.
type UnknownTargetError struct {
	CanonicalID string
}

func (e *UnknownTargetError) Error() string {
	return fmt.Sprintf("modelcatalog: unknown target %q", e.CanonicalID)
}

// Current resolves a profile to its current target.
func (c *Catalog) Current(profile string, opts ResolveOptions) (ResolvedTarget, error) {
	profile = strings.TrimSpace(profile)
	if profile == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	entry, ok := c.profileEntries[profile]
	if !ok {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: profile}
	}

	return c.resolveTarget(profile, profile, profileCompatibilityTarget(entry), opts)
}

// Resolve resolves a profile, canonical target, or alias to a concrete model ID.
func (c *Catalog) Resolve(ref string, opts ResolveOptions) (ResolvedTarget, error) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
	}

	if entry, ok := c.profileEntries[ref]; ok {
		return c.resolveTarget(ref, ref, profileCompatibilityTarget(entry), opts)
	}
	if _, ok := c.manifest.Targets[ref]; ok {
		return c.resolveTarget(ref, "", ref, opts)
	}
	if targetID, ok := c.aliasToID[ref]; ok {
		return c.resolveTarget(ref, "", targetID, opts)
	}

	return ResolvedTarget{}, &UnknownReferenceError{Ref: ref}
}

package modelcatalog

import (
	_ "embed"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
	"github.com/DocumentDrivenDX/fizeau/internal/sampling"
	"gopkg.in/yaml.v3"
)

const (
	statusActive     = "active"
	statusDeprecated = "deprecated"
	statusStale      = "stale"
	maxSchemaVersion = 4

	providerPreferenceLocalFirst        = "local-first"
	providerPreferenceSubscriptionFirst = "subscription-first"
	providerPreferenceLocalOnly         = "local-only"
	providerPreferenceSubscriptionOnly  = "subscription-only"
)

//go:embed catalog/models.yaml
var embeddedManifest []byte

// LoadOptions configures how a catalog manifest is loaded.
type LoadOptions struct {
	ManifestPath    string
	RequireExternal bool
}

// ModelEntry holds per-model metadata introduced in manifest v4.
type ModelEntry struct {
	Family             string                      `yaml:"family,omitempty"`
	DisplayName        string                      `yaml:"display_name,omitempty"`
	Tier               string                      `yaml:"tier,omitempty"`
	Status             string                      `yaml:"status,omitempty"`
	ProviderSystem     string                      `yaml:"provider_system,omitempty"`
	DeploymentClass    string                      `yaml:"deployment_class,omitempty" json:"deployment_class,omitempty"`
	PowerProvenance    PowerProvenance             `yaml:"power_provenance,omitempty" json:"power_provenance,omitempty"`
	CostInputPerM      float64                     `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64                     `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64                     `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64                     `yaml:"cost_cache_write_per_m,omitempty"`
	CostInputPerMTok   float64                     `yaml:"cost_input_per_mtok,omitempty"`
	CostOutputPerMTok  float64                     `yaml:"cost_output_per_mtok,omitempty"`
	SWEBenchVerified   float64                     `yaml:"swe_bench_verified,omitempty"`
	LiveCodeBench      float64                     `yaml:"live_code_bench,omitempty"`
	BenchmarkAsOf      string                      `yaml:"benchmark_as_of,omitempty"`
	OpenRouterID       string                      `yaml:"openrouter_id,omitempty"`
	OpenRouterRefID    string                      `yaml:"openrouter_ref_id,omitempty"`
	Surfaces           map[string]string           `yaml:"surfaces,omitempty"`
	SpeedTokensPerSec  float64                     `yaml:"speed_tokens_per_sec,omitempty"`
	ContextWindow      int                         `yaml:"context_window,omitempty"`
	Power              int                         `yaml:"power,omitempty" json:"power,omitempty"`
	ExactPinOnly       bool                        `yaml:"exact_pin_only,omitempty" json:"exact_pin_only,omitempty"`
	NoTools            bool                        `yaml:"no_tools,omitempty"`
	ReasoningMaxTokens int                         `yaml:"reasoning_max_tokens,omitempty"`
	ReasoningBudgets   map[reasoning.Reasoning]int `yaml:"reasoning_budgets,omitempty"`
	ReasoningLevels    []string                    `yaml:"reasoning_levels,omitempty"`
	ReasoningControl   string                      `yaml:"reasoning_control,omitempty"`
	ReasoningWire      string                      `yaml:"reasoning_wire,omitempty"`
	// SamplingControl declares whether catalog sampling_profiles reach the
	// wire for runs that resolve to this model. See ADR-007 §4.
	//   client_settable (default) — provider honors all five sampler fields.
	//   harness_pinned             — wrapped harness pins samplers internally;
	//                                 the resolver short-circuits to a
	//                                 zero-value bundle.
	//   partial                    — provider honors a subset (reserved; not
	//                                 enforced in v1).
	SamplingControl string `yaml:"sampling_control,omitempty"`
}

// PowerProvenance records why a model received its catalog power score.
type PowerProvenance struct {
	Method          string             `yaml:"method,omitempty" json:"method,omitempty"`
	Benchmarks      map[string]float64 `yaml:"benchmarks,omitempty" json:"benchmarks,omitempty"`
	Recency         string             `yaml:"recency,omitempty" json:"recency,omitempty"`
	CostInputPerM   float64            `yaml:"cost_input_per_m,omitempty" json:"cost_input_per_m,omitempty"`
	CostOutputPerM  float64            `yaml:"cost_output_per_m,omitempty" json:"cost_output_per_m,omitempty"`
	DeploymentClass string             `yaml:"deployment_class,omitempty" json:"deployment_class,omitempty"`
	OverrideReason  string             `yaml:"override_reason,omitempty" json:"override_reason,omitempty"`
}

// Reasoning capability control values.
const (
	ReasoningControlTunable = "tunable"
	ReasoningControlFixed   = "fixed"
	ReasoningControlNone    = "none"

	ReasoningWireProvider = "provider"
	ReasoningWireModelID  = "model_id"
	ReasoningWireNone     = "none"
)

// Sampling-control values for ModelEntry.SamplingControl. See ADR-007 §4.
const (
	SamplingControlClientSettable = "client_settable"
	SamplingControlHarnessPinned  = "harness_pinned"
	SamplingControlPartial        = "partial"
)

type manifest struct {
	Version        int                     `yaml:"version"`
	GeneratedAt    string                  `yaml:"generated_at"`
	CatalogVersion string                  `yaml:"catalog_version,omitempty"`
	Models         map[string]ModelEntry   `yaml:"models,omitempty"`
	Profiles       map[string]profileEntry `yaml:"profiles"`
	Targets        map[string]targetEntry  `yaml:"targets"`
	// SamplingProfiles is a map from profile name (e.g., "code") to a named
	// bundle of sampling-parameter overrides. Profile bundles are the L1
	// layer of the resolution chain; see ADR-007.
	SamplingProfiles map[string]sampling.Profile `yaml:"sampling_profiles,omitempty"`
}

type profileEntry struct {
	Target              string `yaml:"target,omitempty"`
	CompatibilityTarget string `yaml:"compatibility_target,omitempty"`
	MinPower            int    `yaml:"min_power,omitempty"`
	MaxPower            int    `yaml:"max_power,omitempty"`
	ProviderPreference  string `yaml:"provider_preference,omitempty"`
}

// surfaceValue represents a surface entry that may be a plain model ID string
// or a struct with a candidates list (v4+).
type surfaceValue struct {
	// model is set when the YAML value is a plain string.
	model string
	// candidates is set when the YAML value is a struct with a candidates list.
	candidates []string
}

// UnmarshalYAML decodes either a scalar string or a mapping with candidates.
func (s *surfaceValue) UnmarshalYAML(value *yaml.Node) error {
	switch value.Kind {
	case yaml.ScalarNode:
		s.model = value.Value
		return nil
	case yaml.MappingNode:
		var raw struct {
			Candidates []string `yaml:"candidates"`
		}
		if err := value.Decode(&raw); err != nil {
			return err
		}
		s.candidates = raw.Candidates
		return nil
	default:
		return fmt.Errorf("surfaceValue: unexpected YAML node kind %v", value.Kind)
	}
}

// primaryModel returns the first/primary concrete model ID for this surface.
func (s surfaceValue) primaryModel() string {
	if s.model != "" {
		return s.model
	}
	if len(s.candidates) > 0 {
		return s.candidates[0]
	}
	return ""
}

// allCandidates returns an ordered list of candidate model IDs.
func (s surfaceValue) allCandidates() []string {
	if s.model != "" {
		return []string{s.model}
	}
	out := make([]string, len(s.candidates))
	copy(out, s.candidates)
	return out
}

type targetEntry struct {
	Family           string                        `yaml:"family"`
	Aliases          []string                      `yaml:"aliases"`
	Status           string                        `yaml:"status"`
	Replacement      string                        `yaml:"replacement,omitempty"`
	DeprecatedAt     string                        `yaml:"deprecated_at,omitempty"`
	Candidates       []string                      `yaml:"candidates,omitempty"`
	Surfaces         map[string]surfaceValue       `yaml:"surfaces"`
	SurfacePolicy    map[string]surfacePolicyEntry `yaml:"surface_policy,omitempty"`
	ContextWindowMin int                           `yaml:"context_window_min,omitempty"`
	SWEBenchMin      float64                       `yaml:"swe_bench_min,omitempty"`
	// Pricing (USD per 1M tokens, 0 = unknown/free)
	CostInputPerM      float64 `yaml:"cost_input_per_m,omitempty"`
	CostOutputPerM     float64 `yaml:"cost_output_per_m,omitempty"`
	CostCacheReadPerM  float64 `yaml:"cost_cache_read_per_m,omitempty"`
	CostCacheWritePerM float64 `yaml:"cost_cache_write_per_m,omitempty"`
	// Context and hardware
	ContextWindow int `yaml:"context_window,omitempty"` // max tokens
	// Benchmarks
	SWEBenchVerified float64 `yaml:"swe_bench_verified,omitempty"` // percent
	LiveCodeBench    float64 `yaml:"live_code_bench,omitempty"`    // percent
	BenchmarkAsOf    string  `yaml:"benchmark_as_of,omitempty"`    // YYYY-MM-DD
	// OpenRouter
	OpenRouterRefID string `yaml:"openrouter_ref_id,omitempty"` // OR model ID when different from surface model
}

type surfacePolicyEntry struct {
	ReasoningDefault       reasoning.Reasoning `yaml:"reasoning_default,omitempty"`
	PlacementOrder         []string            `yaml:"placement_order,omitempty"`
	MaxInputCostPerMTokUSD *float64            `yaml:"max_input_cost_per_mtok_usd,omitempty"`
	FailurePolicy          string              `yaml:"failure_policy,omitempty"`
}

func (s surfacePolicyEntry) toResolved() SurfacePolicy {
	return SurfacePolicy{
		ReasoningDefault:       s.ReasoningDefault,
		PlacementOrder:         append([]string(nil), s.PlacementOrder...),
		MaxInputCostPerMTokUSD: s.MaxInputCostPerMTokUSD,
		FailurePolicy:          s.FailurePolicy,
	}
}

// Default loads the embedded default catalog snapshot.
func Default() (*Catalog, error) {
	return Load(LoadOptions{})
}

// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
func Load(opts LoadOptions) (*Catalog, error) {
	data := embeddedManifest
	source := "embedded"

	if opts.ManifestPath != "" {
		externalData, err := os.ReadFile(opts.ManifestPath)
		if err != nil {
			if opts.RequireExternal {
				return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
			}
		} else {
			data = externalData
			source = opts.ManifestPath
		}
	}

	return loadManifest(data, source)
}

func loadManifest(data []byte, source string) (*Catalog, error) {
	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
	}
	upgradeManifest(&m)
	if err := validateManifest(m); err != nil {
		return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
	}

	catalog := &Catalog{
		manifest:       m,
		manifestSrc:    source,
		aliasToID:      make(map[string]string),
		profileEntries: make(map[string]profileEntry),
	}

	}

	for profile, entry := range m.Profiles {
		catalog.profileEntries[profile] = entry
	}
	for targetID, target := range m.Targets {
		for _, alias := range target.Aliases {
			catalog.aliasToID[alias] = targetID
		}
	}

	return catalog, nil
}

func validateManifest(m manifest) error {
	if m.Version <= 0 {
		return fmt.Errorf("version must be greater than zero")
	}
	if m.Version > maxSchemaVersion {
		return fmt.Errorf("unsupported schema version %d (max supported %d)", m.Version, maxSchemaVersion)
	}
	if len(m.Targets) == 0 {
		return fmt.Errorf("targets must not be empty")
	}

	reserved := make(map[string]string)
	targetIDs := make([]string, 0, len(m.Targets))
	for targetID := range m.Targets {
		targetIDs = append(targetIDs, targetID)
	}
	sort.Strings(targetIDs)

	for _, targetID := range targetIDs {
		target := m.Targets[targetID]
		if strings.TrimSpace(targetID) == "" {
			return fmt.Errorf("target ID must not be empty")
		}
		if strings.TrimSpace(target.Family) == "" {
			return fmt.Errorf("target %q must define family", targetID)
		}
		if len(target.Surfaces) == 0 && len(target.Candidates) == 0 {
			return fmt.Errorf("target %q must define at least one surface or candidate", targetID)
		}

		status := normalizedStatus(target.Status)
		switch status {
		case statusActive, statusDeprecated, statusStale:
		default:
			return fmt.Errorf("target %q has invalid status %q", targetID, target.Status)
		}

		if target.Replacement != "" {
			if _, ok := m.Targets[target.Replacement]; !ok {
				return fmt.Errorf("target %q replacement %q not found", targetID, target.Replacement)
			}
			if replacementCycle := findReplacementCycle(m, targetID); replacementCycle != "" {
				return fmt.Errorf("target %q replacement chain contains cycle via %q", targetID, replacementCycle)
			}
		}

		if owner, exists := reserved[targetID]; exists {
			return fmt.Errorf("reference %q collides with %s", targetID, owner)
		}
		reserved[targetID] = fmt.Sprintf("target %q", targetID)

		for surface, sv := range target.Surfaces {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface key", targetID)
			}
			if strings.TrimSpace(sv.primaryModel()) == "" {
				return fmt.Errorf("target %q has empty model for surface %q", targetID, surface)
			}
		}
		for surface, policy := range target.SurfacePolicy {
			if strings.TrimSpace(surface) == "" {
				return fmt.Errorf("target %q has empty surface_policy key", targetID)
			}
			if !targetSupportsSurface(m, target, surface) {
				return fmt.Errorf("target %q surface_policy %q has no matching surface mapping", targetID, surface)
			}
			if policy.ReasoningDefault == "" {
				return fmt.Errorf("target %q surface_policy %q must define reasoning_default", targetID, surface)
			}
		}

		if target.CostInputPerM < 0 {
			return fmt.Errorf("target %q cost_input_per_m must be >= 0", targetID)
		}
		if target.CostOutputPerM < 0 {
			return fmt.Errorf("target %q cost_output_per_m must be >= 0", targetID)
		}
		if target.CostCacheReadPerM < 0 {
			return fmt.Errorf("target %q cost_cache_read_per_m must be >= 0", targetID)
		}
		if target.CostCacheWritePerM < 0 {
			return fmt.Errorf("target %q cost_cache_write_per_m must be >= 0", targetID)
		}
		if target.ContextWindow < 0 {
			return fmt.Errorf("target %q context_window must be >= 0", targetID)
		}

		for _, alias := range target.Aliases {
			alias = strings.TrimSpace(alias)
			if alias == "" {
				return fmt.Errorf("target %q has empty alias", targetID)
			}
			if owner, exists := reserved[alias]; exists {
				return fmt.Errorf("alias %q for target %q collides with %s", alias, targetID, owner)
			}
			reserved[alias] = fmt.Sprintf("alias for target %q", targetID)
		}
	}

	for modelID, model := range m.Models {
		if strings.TrimSpace(modelID) == "" {
			return fmt.Errorf("model ID must not be empty")
		}
		status := normalizedStatus(model.Status)
		switch status {
		case statusActive, statusDeprecated, statusStale:
		default:
			return fmt.Errorf("model %q has invalid status %q", modelID, model.Status)
		}
		if model.Tier != "" {
			if _, ok := m.Targets[model.Tier]; !ok {
				return fmt.Errorf("model %q references unknown tier %q", modelID, model.Tier)
			}
		}
		if model.CostInputPerM < 0 || model.CostInputPerMTok < 0 {
			return fmt.Errorf("model %q cost_input_per_m must be >= 0", modelID)
		}
		if model.CostOutputPerM < 0 || model.CostOutputPerMTok < 0 {
			return fmt.Errorf("model %q cost_output_per_m must be >= 0", modelID)
		}
		if model.CostCacheReadPerM < 0 {
			return fmt.Errorf("model %q cost_cache_read_per_m must be >= 0", modelID)
		}
		if model.CostCacheWritePerM < 0 {
			return fmt.Errorf("model %q cost_cache_write_per_m must be >= 0", modelID)
		}
		if model.ContextWindow < 0 {
			return fmt.Errorf("model %q context_window must be >= 0", modelID)
		}
		if model.Power < 0 {
			return fmt.Errorf("model %q power must be >= 0", modelID)
		}
		if model.Power > 10 {
			return fmt.Errorf("model %q power must be <= 10", modelID)
		}
		if model.ReasoningMaxTokens < 0 {
			return fmt.Errorf("model %q reasoning_max_tokens must be >= 0", modelID)
		}
		for level, budget := range model.ReasoningBudgets {
			if budget < 0 {
				return fmt.Errorf("model %q reasoning_budgets %q must be >= 0", modelID, level)
			}
			if model.ReasoningMaxTokens > 0 && budget > model.ReasoningMaxTokens {
				return fmt.Errorf("model %q reasoning_budgets %q exceeds reasoning_max_tokens", modelID, level)
			}
		}
		switch model.ReasoningControl {
		case "", ReasoningControlTunable, ReasoningControlFixed, ReasoningControlNone:
		default:
			return fmt.Errorf("model %q has invalid reasoning_control %q (must be one of tunable, fixed, none)", modelID, model.ReasoningControl)
		}
		switch model.ReasoningWire {
		case "", ReasoningWireProvider, ReasoningWireModelID, ReasoningWireNone:
		default:
			return fmt.Errorf("model %q has invalid reasoning_wire %q (must be one of provider, model_id, none)", modelID, model.ReasoningWire)
		}
		switch model.SamplingControl {
		case "", SamplingControlClientSettable, SamplingControlHarnessPinned, SamplingControlPartial:
		default:
			return fmt.Errorf("model %q has invalid sampling_control %q (must be one of client_settable, harness_pinned, partial)", modelID, model.SamplingControl)
		}
	}

	for targetID, target := range m.Targets {
		for _, modelID := range target.Candidates {
			if strings.TrimSpace(modelID) == "" {
				return fmt.Errorf("target %q has empty candidate", targetID)
			}
			if _, ok := m.Models[modelID]; !ok {
				return fmt.Errorf("target %q references unknown candidate model %q", targetID, modelID)
			}
		}
	}

	profiles := make([]string, 0, len(m.Profiles))
	for profile := range m.Profiles {
		profiles = append(profiles, profile)
	}
	sort.Strings(profiles)

	for _, profile := range profiles {
		entry := m.Profiles[profile]
		if strings.TrimSpace(profile) == "" {
			return fmt.Errorf("profile name must not be empty")
		}
		compatTarget := profileCompatibilityTarget(entry)
		if strings.TrimSpace(entry.Target) != "" && strings.TrimSpace(compatTarget) != "" && strings.TrimSpace(entry.Target) != strings.TrimSpace(compatTarget) {
			return fmt.Errorf("profile %q target and compatibility_target must match when both are set", profile)
		}
		if entry.MinPower < 0 {
			return fmt.Errorf("profile %q min_power must be >= 0", profile)
		}
		if entry.MaxPower < 0 {
			return fmt.Errorf("profile %q max_power must be >= 0", profile)
		}
		if entry.MinPower > 0 && entry.MaxPower > 0 && entry.MinPower > entry.MaxPower {
			return fmt.Errorf("profile %q min_power must be <= max_power", profile)
		}
		if entry.MinPower == 0 && entry.MaxPower == 0 && compatTarget == "" {
			return fmt.Errorf("profile %q must define min_power/max_power or compatibility_target", profile)
		}
		switch entry.ProviderPreference {
		case "", providerPreferenceLocalFirst, providerPreferenceSubscriptionFirst, providerPreferenceLocalOnly, providerPreferenceSubscriptionOnly:
		default:
			return fmt.Errorf("profile %q has invalid provider_preference %q", profile, entry.ProviderPreference)
		}
		if owner, exists := reserved[profile]; exists && profile != compatTarget {
			return fmt.Errorf("profile %q collides with %s", profile, owner)
		}
		reserved[profile] = fmt.Sprintf("profile %q", profile)
	}

	return nil
}

func upgradeManifest(m *manifest) {
	if m.Version >= 4 || len(m.Models) > 0 {
		return
	}
	m.Models = make(map[string]ModelEntry)
	for targetID, target := range m.Targets {
		for surface, sv := range target.Surfaces {
			for _, modelID := range sv.allCandidates() {
				if modelID == "" {
					continue
				}
				entry := m.Models[modelID]
				if entry.Family == "" {
					entry.Family = target.Family
				}
				if entry.Tier == "" {
					entry.Tier = targetID
				}
				if entry.Status == "" {
					entry.Status = normalizedStatus(target.Status)
				}
				if entry.CostInputPerM == 0 {
					entry.CostInputPerM = target.CostInputPerM
				}
				if entry.CostOutputPerM == 0 {
					entry.CostOutputPerM = target.CostOutputPerM
				}
				if entry.CostCacheReadPerM == 0 {
					entry.CostCacheReadPerM = target.CostCacheReadPerM
				}
				if entry.CostCacheWritePerM == 0 {
					entry.CostCacheWritePerM = target.CostCacheWritePerM

		resolved.CostCacheWritePerM = modelEntry.CostCacheWritePerM
		resolved.ContextWindow = modelEntry.ContextWindow
		resolved.SWEBenchVerified = modelEntry.SWEBenchVerified
		resolved.LiveCodeBench = modelEntry.LiveCodeBench
		resolved.BenchmarkAsOf = modelEntry.BenchmarkAsOf
		resolved.OpenRouterRefID = modelEntry.openRouterID()
	}
	return resolved, nil
}

func (c *Catalog) primaryConcreteModel(target targetEntry, surface Surface) (string, ModelEntry, bool) {
	if sv, ok := target.Surfaces[string(surface)]; ok {
		modelID := sv.primaryModel()
		entry, hasEntry := c.manifest.Models[modelID]
		return modelID, entry, hasEntry
	}
	for _, modelID := range target.Candidates {
		entry, ok := c.manifest.Models[modelID]
		if !ok {
			continue
		}
		if concrete := entry.Surfaces[string(surface)]; concrete != "" {
			return concrete, entry, true
		}
	}
	return "", ModelEntry{}, false
}

func (c *Catalog) concreteModelsForSurface(target targetEntry, surface Surface) []string {
	if len(target.Candidates) == 0 {
		if sv, ok := target.Surfaces[string(surface)]; ok {
			return sv.allCandidates()
		}
		return nil
	}
	out := make([]string, 0, len(target.Candidates))
	for _, modelID := range target.Candidates {
		entry, ok := c.manifest.Models[modelID]
		if !ok {
			continue
		}
		if concrete := entry.Surfaces[string(surface)]; concrete != "" {
			out = append(out, concrete)
		}
	}
	return out
}

func targetCandidateIDs(target targetEntry) []string {
	if len(target.Candidates) > 0 {
		out := make([]string, len(target.Candidates))
		copy(out, target.Candidates)
		return out
	}
	seen := make(map[string]bool)
	var out []string
	keys := make([]string, 0, len(target.Surfaces))
	for surface := range target.Surfaces {
		keys = append(keys, surface)
	}
	sort.Strings(keys)
	for _, surface := range keys {
		for _, modelID := range target.Surfaces[surface].allCandidates() {
			if modelID != "" && !seen[modelID] {
				seen[modelID] = true
				out = append(out, modelID)
			}
		}
	}
	return out
}

func (m ModelEntry) inputCostPerM() float64 {
	if m.CostInputPerM != 0 {
		return m.CostInputPerM
	}
	return m.CostInputPerMTok
}

func (m ModelEntry) outputCostPerM() float64 {
	if m.CostOutputPerM != 0 {
		return m.CostOutputPerM
	}
	return m.CostOutputPerMTok
}

func (m ModelEntry) openRouterID() string {
	if m.OpenRouterID != "" {
		return m.OpenRouterID
	}
	return m.OpenRouterRefID
}

// AutoRoutable reports whether a model is eligible for unpinned automatic
// routing. Unknown-power and exact-pin-only entries remain usable by explicit
// model pin when live discovery confirms availability.
func (m ModelEntry) AutoRoutable() bool {
	return normalizedStatus(m.Status) == statusActive && m.Power > 0 && !m.ExactPinOnly
}

