// ProviderConfig describes a single named provider.
type ProviderConfig struct {
	Type      string             `yaml:"type"`               // "openai", "openrouter", "lmstudio", "llama-server", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", or "anthropic"
	BaseURL   string             `yaml:"base_url,omitempty"` // shorthand for one endpoint
	Endpoints []ProviderEndpoint `yaml:"endpoints,omitempty"`
	APIKey    string             `yaml:"api_key,omitempty"`
	Model     string             `yaml:"model,omitempty"`
	// ModelPattern is a case-insensitive regex applied to auto-discovered model
	// IDs when Model is empty. The first matching model returned by /v1/models
	// is used. If the pattern matches nothing, the first available model is
	// used as a fallback.
	ModelPattern string            `yaml:"model_pattern,omitempty"`
	Headers      map[string]string `yaml:"headers"` // extra HTTP headers (OpenRouter, Azure)
	// Reasoning controls model-side reasoning with one scalar value.
	Reasoning reasoning.Reasoning `yaml:"reasoning,omitempty"`
	// MaxTokens is the maximum number of tokens the model may generate per turn.
	// Zero means use the provider's default.
	MaxTokens int `yaml:"max_tokens,omitempty"`
	// ContextWindow is the model's context window in tokens. Used to configure
	// automatic compaction: the compactor triggers when message history approaches
	// this limit. Zero means use the compaction package default (8192).
	ContextWindow int `yaml:"context_window,omitempty"`
	// Sampling overrides the harness defaults for sampling parameters.
	// Any nil/unset field falls through to harness/server defaults.
	Sampling *SamplingProfile `yaml:"sampling,omitempty"`
	// DailyTokenBudget caps total tokens (request + response) the provider
	// may consume per UTC daily window. Zero/absent disables predictive
	// exhaustion for this provider; the actual quota signal from the
	// upstream API is still respected. See fizeau-f2661619.
	DailyTokenBudget int `yaml:"daily_token_budget,omitempty"`
}

// SamplingProfile is the canonical sampling-overrides bundle. The type
// itself lives in internal/sampling so model-catalog entries and provider
// config can share it without a circular import; this alias preserves the
// existing config.SamplingProfile spelling for callers.
type SamplingProfile = sampling.Profile

// ProviderEndpoint describes one serving endpoint for providers that can run
// across multiple host:port locations.
type ProviderEndpoint struct {
	Name    string `yaml:"name,omitempty"`
	BaseURL string `yaml:"base_url"`
}

// EndpointConfig describes one endpoint-first serving target. Unlike
// ProviderConfig, endpoint blocks do not require a user-facing provider name
// or a configured model; routing discovers live model IDs from /v1/models.
type EndpointConfig struct {
	Name      string              `yaml:"name,omitempty"`
	Type      string              `yaml:"type"`
	Host      string              `yaml:"host,omitempty"`
	Port      int                 `yaml:"port,omitempty"`
	BaseURL   string              `yaml:"base_url,omitempty"`
	APIKey    string              `yaml:"api_key,omitempty"`
	Headers   map[string]string   `yaml:"headers,omitempty"`
	Reasoning reasoning.Reasoning `yaml:"reasoning,omitempty"`
}

// ImportMetadata records the last import source for drift detection.
type ImportMetadata struct {
	// Source is the import source ("pi" or "opencode").
	Source string `yaml:"source"`
	// Timestamp is when the import occurred (RFC3339).
	Timestamp string `yaml:"timestamp"`
	// SourceHash is the truncated SHA-256 of the source files.
	SourceHash string `yaml:"source_hash"`
}

// ModelCatalogConfig configures how the shared model catalog is loaded.
type ModelCatalogConfig struct {
	Manifest string `yaml:"manifest,omitempty"`
}

type ToolsConfig struct {
	Bash BashToolConfig `yaml:"bash,omitempty"`
}

// SkillsConfig configures discovery of SKILL.md progressive-disclosure
// skills.
type SkillsConfig struct {
	// Dir is the skills directory. Empty defaults to ".fizeau/skills"
	// relative to the work directory; "-" disables skill discovery
	// even when a directory exists. The FIZEAU_SKILLS_DIR environment
	// variable overrides this value when set.
	Dir string `yaml:"dir,omitempty"`
}

type BashToolConfig struct {
	OutputFilter BashOutputFilterConfig `yaml:"output_filter,omitempty"`
}

type BashOutputFilterConfig struct {
	Mode         string `yaml:"mode,omitempty"`
	RTKBinary    string `yaml:"rtk_binary,omitempty"`
	MaxBytes     int    `yaml:"max_bytes,omitempty"`
	RawOutputDir string `yaml:"raw_output_dir,omitempty"`
}

// RoutingConfig configures model-first route selection defaults.
type RoutingConfig struct {
	// DefaultModel is the default requested model-route key to use when the
	// caller does not set --model, --model-ref, or --provider.
	DefaultModel string `yaml:"default_model,omitempty"`

	// DefaultModelRef resolves through the model catalog to a canonical route
	// key when no explicit provider or model input is supplied.
	DefaultModelRef string `yaml:"default_model_ref,omitempty"`

	// HealthCooldown controls how long a failed candidate remains deprioritized
	// before it is retried.
	HealthCooldown string `yaml:"health_cooldown,omitempty"`

	// HistoryWindow controls how far back observed routing history is sampled
	// when scoring healthy candidates.
	HistoryWindow string `yaml:"history_window,omitempty"`

	// ProbeTimeout controls provider availability/model probes.
	ProbeTimeout string `yaml:"probe_timeout,omitempty"`

	// ReliabilityWeight weights recent success history when scoring healthy
	// candidates.
	ReliabilityWeight float64 `yaml:"reliability_weight,omitempty"`

	// PerformanceWeight weights observed latency/throughput when scoring healthy
	// candidates.
	PerformanceWeight float64 `yaml:"performance_weight,omitempty"`

	// LoadWeight weights recent selection volume when balancing healthy
	// candidates.
	LoadWeight float64 `yaml:"load_weight,omitempty"`

	// CostWeight weights observed known cost when balancing healthy candidates.
	CostWeight float64 `yaml:"cost_weight,omitempty"`

	// CapabilityWeight weights model benchmark capability (swe_bench_verified)
	// when scoring healthy candidates.
	CapabilityWeight float64 `yaml:"capability_weight"`
}

// BackendPoolConfig describes a named routing target that selects one provider
// before a run using a specified strategy.
type BackendPoolConfig struct {
	// ModelRef is the model catalog reference (alias, profile, or canonical
	// target) attached to this backend pool. Optional.
	ModelRef string `yaml:"model_ref,omitempty"`

	// Providers is the ordered list of named provider references.
	Providers []string `yaml:"providers"`

	// Strategy is the provider selection algorithm: "round-robin" or
	// "first-available". Defaults to "first-available" if empty.
	Strategy string `yaml:"strategy,omitempty"`
}

// ProviderOverrides are per-run overrides applied before building a provider.
type ProviderOverrides struct {
	Model           string
	ModelRef        string
	AllowDeprecated bool
}

const (
	projectConfigDir    = ".fizeau"
	globalConfigDirName = "fizeau"
)

func ProjectConfigDirName() string {
	return projectConfigDir
}

func GlobalConfigDirName() string {
	return globalConfigDirName
}

func DefaultSessionLogDir() string {
	return filepath.Join(projectConfigDir, "sessions")
}

func ProjectConfigPath(workDir string) string {
	return filepath.Join(workDir, projectConfigDir, "config.yaml")
}

func GlobalConfigPath(home string) string {
	return filepath.Join(home, ".config", globalConfigDirName, "config.yaml")

	return filepath.Join(home, ".config", globalConfigDirName, "config.yaml")
}

func ProjectRouteHealthPath(workDir, routeKey string) string {
	return filepath.Join(workDir, projectConfigDir, "route-health-"+routeKey+".json")
}

func ProjectRouteStateCounterPath(workDir, routeKey string) string {
	return filepath.Join(workDir, projectConfigDir, "route-state-"+routeKey+".counter")
}

func DefaultModelCatalogManifestPath() string {
	configDir, err := os.UserConfigDir()
	if err != nil {
		return ""
	}
	return filepath.Join(configDir, globalConfigDirName, "models.yaml")
}

func FallbackModelCatalogManifestPath() string {
	return filepath.Join(".config", globalConfigDirName, "models.yaml")
}

// Config is the top-level agent configuration.
type Config struct {
	// Providers is a map of named provider configurations.
	Providers map[string]ProviderConfig `yaml:"providers"`

	// Endpoints is the endpoint-first provider schema. Each entry is expanded
	// into an internal generated provider during finalization.
	Endpoints []EndpointConfig `yaml:"endpoints,omitempty"`

	// Routing configures default model-first resolution behavior.
	Routing RoutingConfig `yaml:"routing,omitempty"`

	// Backends is a map of named backend pool configurations.
	Backends map[string]BackendPoolConfig `yaml:"backends,omitempty"`

	// DefaultBackend is the name of the default backend pool. When set, it
	// takes precedence over Default for runs that do not name a provider
	// or backend explicitly.
	DefaultBackend string `yaml:"default_backend,omitempty"`

	// ModelCatalog configures the optional external manifest path.
	ModelCatalog ModelCatalogConfig `yaml:"model_catalog,omitempty"`

	Tools ToolsConfig `yaml:"tools,omitempty"`

	// Anchors enables anchored read output and the anchor_edit tool for CLI runs.
	Anchors bool `yaml:"anchors,omitempty"`

	// Skills configures progressive-disclosure SKILL.md discovery.
	Skills SkillsConfig `yaml:"skills,omitempty"`

	// Telemetry configures OTel export enablement and runtime-specific
	// pricing keyed by provider system and resolved model.
	Telemetry telemetry.Config `yaml:"telemetry,omitempty"`

	// Default is the name of the default provider. If empty, uses the first.
	Default string `yaml:"default"`

	// MaxIterations limits agent loop iterations.
	MaxIterations int `yaml:"max_iterations"`

	// ReasoningByteLimit is the maximum bytes of pure reasoning_content
	// allowed before the stream is aborted. Default is 256KB.
	// Set to 0 for unlimited (same pattern as max_iterations).
	ReasoningByteLimit int `yaml:"reasoning_byte_limit"`

	// CompactionPercent scales the effective context window used to trigger
	// automatic compaction. Range 1-100. 0 or absent = use default (95%).
	// The actual trigger threshold = context_window × percent/100 - reserve_tokens.
	CompactionPercent int `yaml:"compaction_percent,omitempty"`

	// SessionLogDir is where session logs are written.
	SessionLogDir string `yaml:"session_log_dir"`

	// Preset is the system prompt preset name.
	Preset string `yaml:"preset"`

	// ImportedFrom records the last import source for drift detection.
	ImportedFrom *ImportMetadata `yaml:"imported_from,omitempty"`

	// Legacy flat fields for backwards compatibility.
	LegacyProvider string `yaml:"provider,omitempty"`
	LegacyBaseURL  string `yaml:"base_url,omitempty"`
	LegacyAPIKey   string `yaml:"api_key,omitempty"`
	LegacyModel    string `yaml:"model,omitempty"`

	warnings       []string          `yaml:"-"`
	providerErrors map[string]string `yaml:"-"`
}

// Defaults returns a Config with sensible defaults.
func Defaults() Config {
	return Config{
		MaxIterations:      100,
		SessionLogDir:      DefaultSessionLogDir(),
		Preset:             "default",
		ReasoningByteLimit: agent.DefaultReasoningByteLimit,
	}
}

// Load reads configuration from .fizeau/config.yaml (project) and
// ~/.config/fizeau/config.yaml (global), with env var expansion.
// Project config overrides global config. If no config files exist,
// returns defaults.
func Load(workDir string) (*Config, error) {
	cfg := Defaults()

	// Try global config first, then project config (project wins)
	var paths []string
	if home, err := os.UserHomeDir(); err == nil {
		paths = append(paths, GlobalConfigPath(home))
	}
	paths = append(paths, ProjectConfigPath(workDir))

	for _, p := range paths {
		data, err := safefs.ReadFile(p)
		if err != nil {
			continue
		}
		expanded := expandEnvVars(string(data))
		if err := rejectLegacyProviderReasoningKeys([]byte(expanded)); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
		if err := yaml.Unmarshal([]byte(expanded), &cfg); err != nil {
			return nil, fmt.Errorf("config: parsing %s: %w", p, err)
		}
	}

	// Migrate legacy flat format
	cfg.migrateLegacy()

	// Apply env var overrides to default provider
	cfg.applyEnvOverrides()

	if err := cfg.finalize(); err != nil {
		return nil, err
	}

	return &cfg, nil
}

// migrateLegacy converts old flat fields to a named provider.
func (c *Config) migrateLegacy() {
	if c.Providers != nil && len(c.Providers) > 0 {
		return // new format takes precedence
	}
	if c.LegacyProvider == "" && c.LegacyBaseURL == "" {
		return // nothing to migrate
	}

	provType := c.LegacyProvider
	if provType == "" {
		provType = inferProviderTypeFromBaseURL(c.LegacyBaseURL)
		if provType == "" {
			provType = "lmstudio"
		}
	}
	baseURL := c.LegacyBaseURL
	if baseURL == "" {
		baseURL = "http://localhost:1234/v1"
	}

	c.Providers = map[string]ProviderConfig{
		"default": {
			Type:    provType,
			BaseURL: baseURL,
			APIKey:  c.LegacyAPIKey,
			Model:   c.LegacyModel,
		},
	}
	if c.Default == "" {
		c.Default = "default"
	}
	c.LegacyProvider = ""
	c.LegacyBaseURL = ""
	c.LegacyAPIKey = ""
	c.LegacyModel = ""
}

// applyEnvOverrides applies AGENT_* env vars to the default provider.
func (c *Config) applyEnvOverrides() {
	if v := os.Getenv("FIZEAU_SKILLS_DIR"); v != "" {
		c.Skills.Dir = v
	}

	if c.Providers == nil {
		c.Providers = make(map[string]ProviderConfig)
	}

	// Get or create default provider
	defName := c.defaultNameForEnvOverride()
	p := c.Providers[defName]
	changed := false

	if v := os.Getenv("FIZEAU_PROVIDER"); v != "" {
		p.Type = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_BASE_URL"); v != "" {
		p.BaseURL = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_API_KEY"); v != "" {
		p.APIKey = v
		changed = true
	}
	if v := os.Getenv("FIZEAU_MODEL"); v != "" {
		p.Model = v
		changed = true
	}

	// Sampling overrides forwarded by the benchmark matrix adapter.
	if v := os.Getenv("FIZEAU_TEMPERATURE"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.Temperature = &f
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_TOP_P"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.TopP = &f
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_TOP_K"); v != "" {
		if n, err := strconv.Atoi(v); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.TopK = &n
			changed = true
		}
	}
	if v := os.Getenv("FIZEAU_MIN_P"); v != "" {
		if f, err := strconv.ParseFloat(v, 64); err == nil {
			if p.Sampling == nil {
				p.Sampling = &SamplingProfile{}
			}
			p.Sampling.MinP = &f
			changed = true
		}
	}

	if changed {
		if p.Type == "" {
			p.Type = inferProviderTypeFromBaseURL(p.BaseURL)
			if p.Type == "" {
				p.Type = "lmstudio"
			}
		}
		c.Providers[defName] = p
		if c.Default == "" {
			c.Default = defName
		}
	}
}

// DefaultName returns the name of the default provider.
func (c *Config) DefaultName() string {
	if c.Default != "" {
		return c.Default
	}
	// Return first provider name
	for name := range c.Providers {
		return name
	}
	return "default"
}

func (c *Config) defaultNameForEnvOverride() string {
	if c.Default != "" {
		return c.Default
	}
	if len(c.Providers) == 1 {
		for name := range c.Providers {
			return name
		}
	}
	return "default"
}

// ProviderNames returns configured provider names in stable order.
func (c *Config) ProviderNames() []string {
	if c.Providers == nil {
		return nil
	}
	// Put default first, then alphabetical
	var names []string
	defName := c.DefaultName()
	if _, ok := c.Providers[defName]; ok {
		names = append(names, defName)
	}

package fizeau

import (
	"context"
	"fmt"
	"sort"

	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
)

func (s *service) ListProfiles(_ context.Context) ([]ProfileInfo, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	meta := cat.Metadata()
	profiles := cat.Profiles()
	aliases := cat.Aliases()
	out := make([]ProfileInfo, 0, len(profiles)+len(aliases))
	seen := make(map[string]struct{}, len(profiles)+len(aliases))
	for _, profile := range profiles {
		info := ProfileInfo{
			Name:                profile.Name,
			Target:              profile.Target,
			CompatibilityTarget: profile.CompatibilityTarget,
			MinPower:            profile.MinPower,
			MaxPower:            profile.MaxPower,
			ProviderPreference:  profile.ProviderPreference,
			CatalogVersion:      meta.CatalogVersion,
			ManifestSource:      meta.ManifestSource,
			ManifestVersion:     meta.ManifestVersion,
		}
		if profile.CompatibilityTarget != "" && profile.Name != profile.CompatibilityTarget {
			info.AliasOf = profile.CompatibilityTarget
		}
		out = append(out, info)
		seen[profile.Name] = struct{}{}
	}
	for _, alias := range aliases {
		if _, ok := seen[alias.Name]; ok {
			continue
		}
		out = append(out, ProfileInfo{
			Name:            alias.Name,
			Target:          alias.Target,
			AliasOf:         alias.Target,
			Deprecated:      alias.Deprecated,
			Replacement:     alias.Replacement,
			CatalogVersion:  meta.CatalogVersion,
			ManifestSource:  meta.ManifestSource,
			ManifestVersion: meta.ManifestVersion,
		})
	}
	sort.Slice(out, func(i, j int) bool {
		return out[i].Name < out[j].Name
	})
	return out, nil
}

func (s *service) ProfileAliases(_ context.Context) (map[string]string, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	out := make(map[string]string)
	for _, profile := range cat.Profiles() {
		if profile.CompatibilityTarget != "" && profile.Name != profile.CompatibilityTarget {
			out[profile.Name] = profile.CompatibilityTarget
		}
	}
	for _, alias := range cat.Aliases() {
		target := alias.Target
		if alias.Deprecated && alias.Replacement != "" {
			target = alias.Replacement
		}
		out[alias.Name] = target
	}
	return out, nil
}

func (s *service) ResolveProfile(_ context.Context, name string) (*ResolvedProfile, error) {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil, err
	}
	meta := cat.Metadata()
	profile, ok := cat.Profile(name)
	var compatTarget string
	var deprecated bool
	var replacement string
	if ok {
		compatTarget = profile.CompatibilityTarget
		if compatTarget == "" {
			compatTarget = profile.Target
		}
	}
	if !ok {
		var aliasTarget string
		for _, surface := range serviceProfileSurfaces() {
			target, err := cat.Resolve(name, modelcatalog.ResolveOptions{
				Surface:         surface.catalogSurface,
				AllowDeprecated: true,
			})
			if err != nil {
				if _, ok := err.(*modelcatalog.MissingSurfaceError); ok {
					continue
				}
				return nil, err
			}
			aliasTarget = target.CanonicalID
			if target.Deprecated && target.Replacement != "" {
				deprecated = true
				replacement = target.Replacement
				aliasTarget = target.Replacement
			} else if target.Deprecated {
				deprecated = true
			}
			break
		}
		if aliasTarget == "" {
			return nil, fmt.Errorf("profile %q is not defined in the catalog", name)
		}
		if resolvedProfile, ok := cat.Profile(aliasTarget); ok {
			profile = resolvedProfile
			compatTarget = profile.CompatibilityTarget
			if compatTarget == "" {
				compatTarget = profile.Target
			}
		} else {
			for _, candidate := range cat.Profiles() {
				if candidate.CompatibilityTarget == aliasTarget || candidate.Target == aliasTarget {
					profile = candidate
					compatTarget = candidate.CompatibilityTarget
					if compatTarget == "" {
						compatTarget = candidate.Target
					}
					break
				}
			}
		}
	}
	if compatTarget == "" {
		return nil, fmt.Errorf("profile %q has no compatibility target", name)
	}

	var resolved *ResolvedProfile
	for _, surface := range serviceProfileSurfaces() {
		target, err := cat.Resolve(compatTarget, modelcatalog.ResolveOptions{
			Surface:         surface.catalogSurface,
			AllowDeprecated: true,
		})
		if err != nil {
			if _, ok := err.(*modelcatalog.MissingSurfaceError); ok {
				continue
			}
			return nil, err
		}
		if resolved == nil {
			resolved = &ResolvedProfile{
				Name:                name,
				Target:              compatTarget,
				CompatibilityTarget: compatTarget,
				MinPower:            profile.MinPower,
				MaxPower:            profile.MaxPower,
				Deprecated:          deprecated || target.Deprecated,
				Replacement:         replacement,
				CatalogVersion:      meta.CatalogVersion,
				ManifestSource:      meta.ManifestSource,
				ManifestVersion:     meta.ManifestVersion,
			}
		}
		resolved.Surfaces = append(resolved.Surfaces, ProfileSurface{
			Name:                    surface.name,
			Harness:                 surface.harness,
			ProviderSystem:          surface.providerSystem,
			Model:                   target.ConcreteModel,
			PlacementOrder:          append([]string(nil), target.SurfacePolicy.PlacementOrder...),
			CostCeilingInputPerMTok: cloneFloat64(target.SurfacePolicy.MaxInputCostPerMTokUSD),
			ReasoningDefault:        Reasoning(target.SurfacePolicy.ReasoningDefault),
			FailurePolicy:           target.SurfacePolicy.FailurePolicy,
		})
	}
	if resolved == nil {
		return nil, fmt.Errorf("profile %q has no service-supported surface", name)
	}
	sort.Slice(resolved.Surfaces, func(i, j int) bool {
		return resolved.Surfaces[i].Name < resolved.Surfaces[j].Name
	})
	return resolved, nil
}

type serviceProfileSurface struct {
	name           string
	harness        string
	providerSystem string
	catalogSurface modelcatalog.Surface
}

func serviceProfileSurfaces() []serviceProfileSurface {
	return []serviceProfileSurface{
		{name: "native-anthropic", harness: "agent", providerSystem: "anthropic", catalogSurface: modelcatalog.SurfaceAgentAnthropic},
		{name: "native-openai", harness: "agent", providerSystem: "openai-compatible", catalogSurface: modelcatalog.SurfaceAgentOpenAI},
		{name: "codex", harness: "codex", providerSystem: "openai", catalogSurface: modelcatalog.SurfaceCodex},
		{name: "claude", harness: "claude", providerSystem: "anthropic", catalogSurface: modelcatalog.SurfaceClaudeCode},
		{name: "gemini", harness: "gemini", providerSystem: "google", catalogSurface: modelcatalog.SurfaceGemini},
	}
}

func cloneFloat64(v *float64) *float64 {
	if v == nil {
		return nil
	}
	cp := *v
	return &cp
}

package fizeau

import (
	"context"
	"fmt"
	"io"
	"path/filepath"
	"sync"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
	geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/serviceimpl"
	sessionusage "github.com/DocumentDrivenDX/fizeau/internal/session"
)

// FizeauService is the entire public Go surface of the fizeau module.
// See CONTRACT-003 for the full specification.
type FizeauService interface {
	Execute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error)
	TailSessionLog(ctx context.Context, sessionID string) (<-chan ServiceEvent, error)
	ListHarnesses(ctx context.Context) ([]HarnessInfo, error)
	ListProviders(ctx context.Context) ([]ProviderInfo, error)
	ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error)
	ListProfiles(ctx context.Context) ([]ProfileInfo, error)
	ResolveProfile(ctx context.Context, name string) (*ResolvedProfile, error)
	ProfileAliases(ctx context.Context) (map[string]string, error)
	HealthCheck(ctx context.Context, target HealthTarget) error
	ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error)
	RecordRouteAttempt(ctx context.Context, attempt RouteAttempt) error
	RouteStatus(ctx context.Context) (*RouteStatusReport, error)

	// Historical session-log projections. CONTRACT-003 owns these so CLI
	// subcommands such as log/replay/usage do not need to read the
	// internal session-log JSONL schema.
	UsageReport(ctx context.Context, opts UsageReportOptions) (*UsageReport, error)
	ListSessionLogs(ctx context.Context) ([]SessionLogEntry, error)
	WriteSessionLog(ctx context.Context, sessionID string, w io.Writer) error
	ReplaySession(ctx context.Context, sessionID string, w io.Writer) error
}

// ServiceConfig provides provider and routing data to the service without
// creating an import cycle from the root package into agent/config.
// Callers wrap their loaded *config.Config in a type that satisfies this interface.
type ServiceConfig interface {
	// ProviderNames returns provider names in stable order (default first).
	ProviderNames() []string
	// DefaultProviderName returns the name of the configured default provider.
	DefaultProviderName() string
	// Provider returns the raw config values for a named provider.
	Provider(name string) (ServiceProviderEntry, bool)
	// HealthCooldown returns the configured cooldown duration (0 = use default 30s).
	HealthCooldown() time.Duration
	// WorkDir is the base directory for file-backed health state.
	WorkDir() string
	// SessionLogDir returns the configured sessions directory.
	SessionLogDir() string
}

// ServiceProviderEntry carries the minimal provider data the service needs.
type ServiceProviderEntry struct {
	Type      string // "openai" | "openrouter" | "lmstudio" | "llama-server" | "omlx" | "lucebox" | "vllm" | "rapid-mlx" | "ollama" | "anthropic"
	BaseURL   string
	Endpoints []ServiceProviderEndpoint
	APIKey    string
	Model     string // configured default model (may be empty)
	// ConfigError marks this provider entry invalid while allowing the rest of
	// the service config to load. Invalid providers are reported in status
	// surfaces and excluded from routing.
	ConfigError string
	// DailyTokenBudget is the operator-configured per-UTC-day token budget
	// (request + response) for this provider. Zero means no local burn-rate
	// prediction; the provider's own quota signal still applies.
	DailyTokenBudget int
}

// ServiceProviderEndpoint is one configured provider serving endpoint.
type ServiceProviderEndpoint struct {
	Name    string
	BaseURL string
}

// ServiceOptions configures a FizeauService instance.
//
// seamOptions is embedded so production builds (no testseam tag) get an
// empty struct — making it a compile-time error to set seam fields without
// the build tag. Test builds inherit the four CONTRACT-003 seams
// (FakeProvider, PromptAssertionHook, CompactionAssertionHook,
// ToolWiringHook) automatically.
type ServiceOptions struct {
	seamOptions

	ConfigPath string    // optional override; default $XDG_CONFIG_HOME/fizeau/config.yaml
	Logger     io.Writer // optional; agent writes structured session logs internally regardless

	// ServiceConfig, when non-nil, supplies provider and routing data for
	// ListProviders and HealthCheck. Pass a value wrapping the loaded config.
	// When nil, those methods return an error.
	ServiceConfig ServiceConfig

	// QuotaRefreshDebounce is the minimum interval between live quota probes for
	// a primary subscription harness. Zero uses the service default.
	QuotaRefreshDebounce time.Duration
	// QuotaRefreshStartupWait bounds startup waiting when the durable quota
	// cache is missing, stale, or incomplete. Zero uses the service default.
	QuotaRefreshStartupWait time.Duration
	// QuotaRefreshInterval enables periodic refresh for long-running server
	// processes. Zero disables the timer; cache refresh still happens on startup
	// and service activity.
	QuotaRefreshInterval time.Duration
	// QuotaRefreshContext optionally cancels the periodic server refresh worker.
	// When nil, the worker uses context.Background().
	QuotaRefreshContext context.Context

	// CatalogProbeTimeout bounds live /v1/models discovery during routing.
	// Zero uses the service default of 2s.
	CatalogProbeTimeout time.Duration
	// CatalogRefreshTimeout bounds stale-while-revalidate catalog refreshes.
	// Zero uses the service default of 30s.
	CatalogRefreshTimeout time.Duration

	// LocalCostUSDPer1kTokens is the operator-supplied electricity/operations
	// estimate for local endpoint providers under the embedded agent harness.
	// Zero means local endpoint cost is unknown.
	LocalCostUSDPer1kTokens float64
	// SubscriptionCostCurve optionally overrides the default subscription
	// effective-cost curve used by routing.
	SubscriptionCostCurve *SubscriptionCostCurve

	// SessionLogDir overrides the directory used by historical session-log
	// projections (UsageReport, ListSessionLogs, WriteSessionLog,
	// ReplaySession). Empty falls back to ServiceConfig.SessionLogDir().
	// Per-Execute requests still set their own
	// ServiceExecuteRequest.SessionLogDir.
	SessionLogDir string

	// StaleHarnessReaperGrace is the minimum age before a startup reaper may
	// terminate an owned subprocess record. Zero uses the default grace window.
	StaleHarnessReaperGrace time.Duration
}

// SubscriptionCostCurve tunes effective subscription cost by quota utilization.
// Thresholds are percentages used, and multipliers are applied to the
// equivalent pay-per-token catalog rate.
type SubscriptionCostCurve struct {
	FreeUntilPercent   int
	LowUntilPercent    int
	MediumUntilPercent int
	LowMultiplier      float64
	MediumMultiplier   float64
	HighMultiplier     float64
}

// QuotaState is a live quota snapshot for a harness. Nil means not applicable.
type QuotaState struct {
	Windows    []harnesses.QuotaWindow `json:"windows"`
	CapturedAt time.Time               `json:"captured_at"`
	Fresh      bool                    `json:"fresh"`
	Source     string                  `json:"source,omitempty"`
	Status     string                  `json:"status,omitempty"` // ok|stale|unavailable|unauthenticated|unknown
	LastError  *StatusError            `json:"last_error,omitempty"`
}

// StatusError describes the most recent normalized status error for a harness,
// provider, or endpoint.
type StatusError struct {
	Type      string    // unavailable|unauthenticated|error
	Detail    string    // human-readable detail, safe for diagnostics
	Source    string    // config path, endpoint, cache path, or probe name
	Timestamp time.Time // zero when the source did not include a timestamp
}

// AccountStatus describes authentication/account state without exposing
// provider-specific native files to consumers.
type AccountStatus struct {
	Authenticated   bool
	Unauthenticated bool
	Email           string
	PlanType        string
	OrgName         string
	Source          string
	CapturedAt      time.Time
	Fresh           bool
	Detail          string
}

// UsageWindow describes normalized usage attribution over a time window.
// Empty token/cost totals mean the service has no historical usage source yet.
type UsageWindow struct {
	Name                string
	Source              string
	CapturedAt          time.Time
	Fresh               bool
	InputTokens         int
	OutputTokens        int
	TotalTokens         int
	CacheReadTokens     int
	CacheWriteTokens    int
	ReasoningTokens     int
	CostUSD             float64
	KnownCostUSD        *float64
	UnknownCostSessions int
}

// EndpointStatus describes one configured provider endpoint probe.
type EndpointStatus struct {
	Name          string
	BaseURL       string
	ProbeURL      string
	Status        string // connected|unreachable|unauthenticated|error|unknown
	Source        string
	CapturedAt    time.Time
	Fresh         bool
	LastSuccessAt time.Time
	ModelCount    int
	LastError     *StatusError
}

package fizeau_test

import (
	"context"
	"testing"

	fizeau "github.com/DocumentDrivenDX/fizeau"
)

func TestServiceProfiles_ListResolveAliases(t *testing.T) {
	svc, err := fizeau.New(fizeau.ServiceOptions{})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	profiles, err := svc.ListProfiles(context.Background())
	if err != nil {
		t.Fatalf("ListProfiles: %v", err)
	}
	byName := make(map[string]fizeau.ProfileInfo)
	for _, profile := range profiles {
		byName[profile.Name] = profile
	}
	if byName["smart"].AliasOf != "code-high" {
		t.Fatalf("smart AliasOf: got %q, want code-high", byName["smart"].AliasOf)
	}
	if byName["smart"].CompatibilityTarget != "code-high" || byName["smart"].MinPower != 9 || byName["smart"].MaxPower != 10 {
		t.Fatalf("smart profile policy: %#v", byName["smart"])
	}
	if byName["cheap"].CompatibilityTarget != "code-economy" || byName["cheap"].MinPower != 5 || byName["cheap"].MaxPower != 5 {
		t.Fatalf("cheap profile policy: %#v", byName["cheap"])
	}
	if byName["standard"].CatalogVersion == "" {
		t.Fatal("CatalogVersion should be populated")
	}
	if byName["default"].CompatibilityTarget != "code-medium" || byName["default"].ProviderPreference != "local-first" {
		t.Fatalf("default profile: %#v, want compatibility target code-medium/local-first", byName["default"])
	}
	if byName["local"].CompatibilityTarget != "code-economy" || byName["local"].ProviderPreference != "local-only" {
		t.Fatalf("local profile: %#v, want compatibility target code-economy/local-only", byName["local"])
	}
	if !byName["claude-sonnet"].Deprecated {
		t.Fatal("claude-sonnet should be listed as a deprecated alias")
	}
	if byName["claude-sonnet"].Replacement != "code-medium" {
		t.Fatalf("claude-sonnet Replacement: got %q, want code-medium", byName["claude-sonnet"].Replacement)
	}

	aliases, err := svc.ProfileAliases(context.Background())
	if err != nil {
		t.Fatalf("ProfileAliases: %v", err)
	}
	if aliases["smart"] != "code-high" {
		t.Fatalf("smart alias: got %q, want code-high", aliases["smart"])
	}
	if aliases["claude-sonnet"] != "code-medium" {
		t.Fatalf("deprecated claude-sonnet alias: got %q, want code-medium", aliases["claude-sonnet"])
	}
}

func TestServiceProfiles_ResolveProfile(t *testing.T) {
	svc, err := fizeau.New(fizeau.ServiceOptions{})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	resolved, err := svc.ResolveProfile(context.Background(), "smart")
	if err != nil {
		t.Fatalf("ResolveProfile: %v", err)
	}
	if resolved.Target != "code-high" || resolved.CompatibilityTarget != "code-high" || resolved.MinPower != 9 || resolved.MaxPower != 10 {
		t.Fatalf("profile policy: %#v", resolved)
	}
	if len(resolved.Surfaces) == 0 {
		t.Fatal("expected profile surfaces")
	}
	nativeOpenAI := findProfileSurface(resolved.Surfaces, "native-openai")
	if nativeOpenAI == nil {
		t.Fatalf("native-openai surface missing from %#v", resolved.Surfaces)
	}
	if nativeOpenAI.Harness != "agent" {
		t.Fatalf("native-openai Harness: got %q, want agent", nativeOpenAI.Harness)
	}
	if nativeOpenAI.Model == "" {
		t.Fatalf("native-openai model missing: %#v", nativeOpenAI)
	}
	if len(nativeOpenAI.Candidates) != 0 {
		t.Fatalf("native-openai should not expose a closed candidate set: %#v", nativeOpenAI.Candidates)
	}
	if nativeOpenAI.ReasoningDefault != fizeau.ReasoningHigh {
		t.Fatalf("ReasoningDefault: got %q, want high", nativeOpenAI.ReasoningDefault)
	}
	if nativeOpenAI.FailurePolicy != "ordered-failover" {
		t.Fatalf("FailurePolicy: got %q, want ordered-failover", nativeOpenAI.FailurePolicy)
	}
	if nativeOpenAI.CostCeilingInputPerMTok == nil || *nativeOpenAI.CostCeilingInputPerMTok != 20 {
		t.Fatalf("CostCeilingInputPerMTok: got %#v, want 20", nativeOpenAI.CostCeilingInputPerMTok)
	}

	gemini := findProfileSurface(resolved.Surfaces, "gemini")
	if gemini == nil {
		t.Fatalf("gemini surface missing from %#v", resolved.Surfaces)
	}
	if gemini.Harness != "gemini" || gemini.Model != "gemini-2.5-pro" {
		t.Fatalf("gemini smart surface: %#v", gemini)
	}
	if gemini.ReasoningDefault != fizeau.ReasoningOff {
		t.Fatalf("gemini ReasoningDefault: got %q, want off", gemini.ReasoningDefault)
	}
	if len(gemini.Candidates) != 0 {
		t.Fatalf("gemini should not expose a closed candidate set: %#v", gemini.Candidates)
	}
}

func TestServiceProfiles_ResolveDeprecatedAliasAndUnknown(t *testing.T) {
	svc, err := fizeau.New(fizeau.ServiceOptions{})
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	deprecated, err := svc.ResolveProfile(context.Background(), "claude-sonnet")
	if err != nil {
		t.Fatalf("ResolveProfile deprecated alias: %v", err)
